// Displays walkthrough: DS-1..DS-5, ST-1, ST-3. Usage: node tools/test-displays.js
const path = require('path');
const { chromium } = require(process.env.PW || '/tmp/pw/node_modules/playwright');
let n = 0;
const ok = (c, m) => { if (!c) throw new Error('FAIL: ' + m); console.log('  ok  ' + m); };
(async () => {
  const b = await chromium.launch({ channel: process.env.PW_CHANNEL || undefined });
  const p = await b.newPage({ viewport: { width: 1440, height: 900 } });
  const errs = [];
  p.on('pageerror', (e) => errs.push('pageerror: ' + e.message));
  p.on('console', (m) => m.type() === 'error' && errs.push('console: ' + m.text()));
  await p.goto('file://' + path.resolve(__dirname, '../index.html'));
  await p.waitForTimeout(500);
  const shot = (name) => p.screenshot({ path: `/tmp/displays-${String(++n).padStart(2, '0')}-${name}.png` });
  const txt = (s) => p.evaluate((s) => (document.querySelector(s) || {}).textContent || '', s);
  const setRange = (sel, v) => p.evaluate(([s, v]) => { const e = document.querySelector(s); e.value = v; e.dispatchEvent(new Event('input', { bubbles: true })); }, [sel, v]);
  const popOpen = async () => { if (await p.$('#pop:not([hidden]) .dp-pop')) return; await p.click('[data-mb=displays]'); await p.waitForSelector('#pop .dp-pop'); };
  const popClose = async () => { await p.keyboard.press('Escape'); };
  const scn = async (key) => { await p.click('[data-mb=scn]'); await p.click(`[data-s="${key}"]`); await p.keyboard.press('Escape'); };
  const op = (id) => p.evaluate((id) => parseFloat(document.getElementById(id).style.opacity || '0'), id);
  const near = (a, b) => Math.abs(a - b) < 0.002;
  const br = (id) => p.evaluate((id) => OS.data.displays.list.find((x) => x.id === id).brightness, id);
  const night = () => p.evaluate(() => OS.data.displays.night);
  const aria = (s) => p.getAttribute(s, 'aria-checked');
  const openView = async () => { await p.click('[data-go=displays]'); await p.waitForSelector('.dp-view'); };

  console.log('DS-1 popover');
  ok(near(await op('dim'), 0.18) && (await op('warm')) === 0, 'desk dimmed from built-in 70% (dim .18), no warmth');
  await popOpen();
  let t = await txt('#pop');
  ok(!!(await p.$('#pop [data-b="*"]')), 'link on: one master slider');
  ok(/All displays/.test(t) && /Night Look/.test(t) && /Display settings/.test(t), 'master label, Night Look, footer');
  for (const nm of ['Day', 'Night', 'Cinema']) ok(!!(await p.$(`#pop .dp-chip:text-is("${nm}")`)), `preset chip ${nm}`);
  console.log('DS-4 / ST-3 unsupported DDC');
  ok(/Brightness control unavailable/.test(t) && /DDC\/CI/.test(t) && /LG TV/.test(t), 'TV shows unsupported placeholder with DDC/CI');
  ok((await p.$$('#pop input[type=range]')).length === 1 && !(await p.$('#pop [data-b="tv"]')), 'no slider for the TV');
  ok(!!(await p.$('#pop .state.unsupported.compact')), 'placeholder is the compact unsupported state');
  await shot('popover');
  await setRange('#pop [data-b="*"]', 40);
  ok((await br('builtin')) === 0.4 && (await br('dell')) === 0.4, 'master slider moves every supported display to 40%');
  ok(near(await op('dim'), 0.36), 'desk dims (.36)');
  ok((await p.inputValue('#pop [data-b="*"]')) === '40', 'slider keeps value');

  console.log('DS-2 Night Look');
  await p.click('#pop [data-night]');
  ok((await night()) === true && (await aria('#pop [data-night]')) === 'true', 'Night Look on');
  ok(near(await op('warm'), 0.175), 'desk tinted: warmth 50% * .35');
  await shot('popover-night');

  console.log('DS-3 presets');
  await p.click('#pop .dp-chip:text-is("Day")');
  ok((await br('builtin')) === 0.9 && (await br('dell')) === 0.8 && (await night()) === false, 'Day applied: values + night off');
  ok(near(await op('dim'), 0.06) && (await op('warm')) === 0, 'desk follows (dim .06, no warmth)');
  ok(await p.$eval('#pop .dp-chip:text-is("Day")', (e) => e.classList.contains('on')), 'Day chip highlighted');
  await p.click('#pop .dp-chip:text-is("Night")');
  ok((await night()) === true && (await br('builtin')) === 0.35, 'Night preset applied (night on, 35%)');
  ok(near(await op('warm'), 0.175), 'warmth on desk after preset');

  console.log('DS-5 popover -> view');
  await p.click('#pop [data-set]'); await p.waitForSelector('.dp-view');
  ok((await aria('.pane [data-night]')) === 'true', 'pane Night Look on');
  ok((await p.inputValue('.pane [data-b="builtin"]')) === '35' || (await p.inputValue('.pane [data-b="builtin"]')) === '35', 'pane slider = 35 (from preset)');
  ok(await p.$eval('.dp-plist .row.sel', (e) => /Night/.test(e.textContent)), 'Night preset row highlighted in view');
  ok(/35%/.test(await txt('.dp-rect.sel')), 'arrangement rect shows 35%');
  ok((await p.$$('.dp-rect')).length === 3, 'arrangement has 3 displays');
  await shot('view');

  console.log('DS-5 pane -> popover + desk');
  await setRange('.pane [data-b="builtin"]', 90);
  ok((await br('builtin')) === 0.9 && (await br('dell')) === 0.9, 'linked: pane slider moves all supported (90)');
  ok(near(await op('dim'), 0.06), 'desk instantly follows pane (dim .06)');
  ok(/90%/.test(await txt('.dp-rect.sel')), 'rect label updated live');
  await p.click('.pane [data-night]');
  ok((await night()) === false && (await op('warm')) === 0, 'pane Night Look off clears warmth');
  await p.click('.pane [data-night]');
  await setRange('.pane [data-k="displays.warmth"]', 100);
  ok(near(await op('warm'), 0.35), 'warmth 100% → desk .35');
  await popOpen();
  ok((await p.inputValue('#pop [data-b="*"]')) === '90', 'popover master = 90 (from pane)');
  ok((await aria('#pop [data-night]')) === 'true' && /warmth 100%/.test(await txt('#pop')), 'popover Night Look + warmth 100% (from pane)');
  console.log('DS-5 live while popover open (Preferences/pane change pushes in place)');
  await p.evaluate(() => OS.setPref('displays.warmth', 60));
  ok(/warmth 60%/.test(await txt('#pop')), 'open popover follows warmth pref');
  await p.evaluate(() => OS.setPref('displays.step', 10));
  ok((await p.getAttribute('#pop [data-b="*"]', 'step')) === '10', 'popover step attr = 10 after pref change');
  await p.evaluate(() => OS.setPref('displays.step', 5));

  console.log('Preferences -> popover');
  await p.click('[data-go=prefs]'); await p.waitForSelector('#ps-displays');
  ok(/Link brightness/.test(await txt('#ps-displays')) && /Slider step/.test(await txt('#ps-displays')) && /warmth/i.test(await txt('#ps-displays')), 'Preferences has Displays section');
  await p.click('#ps-displays .seg[data-k="displays.step"] button[data-v="10"]');
  await shot('preferences');
  await popOpen();
  ok((await p.getAttribute('#pop [data-b="*"]', 'step')) === '10', 'step 10 reaches popover slider');
  await popClose();
  await openView();
  ok((await p.getAttribute('.pane [data-b="builtin"]', 'step')) === '10', 'step 10 reaches pane slider');
  await p.click('.pane .seg[data-k="displays.step"] button[data-v="1"]');
  ok((await p.getAttribute('.pane [data-b="builtin"]', 'step')) === '1', 'pane step change → pane slider step 1');
  await p.click('.pane .seg[data-k="displays.step"] button[data-v="5"]');

  console.log('link off');
  await p.click('.pane [data-k="displays.link"]');
  ok((await aria('.pane [data-k="displays.link"]')) === 'false', 'link toggled off in pane');
  await popOpen();
  ok(!(await p.$('#pop [data-b="*"]')) && !!(await p.$('#pop [data-b="builtin"]')) && !!(await p.$('#pop [data-b="dell"]')), 'popover: one slider per display');
  await setRange('#pop [data-b="builtin"]', 20);
  ok((await br('builtin')) === 0.2 && (await br('dell')) === 0.9, 'unlinked: only built-in moved');
  await shot('popover-unlinked');
  console.log('DS-5 popover -> view (selected display)');
  await p.click('#pop [data-set]'); await p.waitForSelector('.dp-view');
  ok((await p.inputValue('.pane [data-b="builtin"]')) === '20', 'pane shows 20');
  await p.click('.dp-rect[data-d="dell"]');
  ok(/DELL/.test(await txt('.pane [data-sel]')) && (await p.inputValue('.pane [data-b="dell"]')) === '90', 'select Dell → pane shows its 90');
  await setRange('.pane [data-b="dell"]', 55);
  ok((await br('dell')) === 0.55 && (await br('builtin')) === 0.2, 'unlinked pane edit moves only Dell');
  console.log('DS-4 select TV');
  await p.click('.dp-rect[data-d="tv"]');
  ok(/Brightness control unavailable/.test(await txt('.pane [data-sel]')) && !(await p.$('.pane [data-sel] input[type=range]')), 'pane: unsupported placeholder, no dead slider');
  await shot('view-unsupported');
  await p.click('.pane [data-k="displays.link"]');

  console.log('DS-3 save / apply / delete');
  ok((await p.isDisabled('[data-save]')), 'save disabled without a name');
  await setRange('.pane [data-b="tv"]', 1).catch(() => {});
  await p.click('.dp-rect[data-d="builtin"]');
  await setRange('.pane [data-b="builtin"]', 65);
  await p.fill('[data-name]', 'Focus');
  await p.click('[data-save]');
  const saved = await p.evaluate(() => OS.data.displays.presets.find((x) => x.name === 'Focus'));
  ok(saved && saved.values.builtin === 0.65 && saved.values.dell === 0.65 && saved.night === true, 'Focus saved with current values + night state');
  ok((await p.inputValue('[data-name]')) === '', 'name field cleared');
  ok(/Focus/.test(await txt('.dp-plist')) && /Built-in 65%/.test(await txt('.dp-plist')), 'preset listed with values');
  await shot('view-presets');
  await popOpen();
  ok(!!(await p.$('#pop .dp-chip:text-is("Focus")')), 'new preset appears as a popover chip');
  await popClose();
  await p.click('.dp-plist [data-apply="p-day"]');
  ok((await br('builtin')) === 0.9 && (await night()) === false, 'Apply from view list');
  /* D9: clicking the row applies; the matching preset shows an Applied indicator */
  ok(await p.$eval('.dp-plist .row[data-p="p-day"]', (e) => e.classList.contains('applied') && !!e.querySelector('[data-applied]')) && (await p.$$('.dp-plist [data-applied]')).length === 1, 'D9 the preset matching current values shows Applied');
  await p.click('.dp-plist .row[data-p="p-cinema"] .t');
  ok(Math.abs((await br('builtin')) - 0.5) < 0.005, 'D9 clicking the preset row applies it');
  ok(await p.$eval('.dp-plist .row[data-p="p-cinema"]', (e) => !!e.querySelector('[data-applied]')) && !(await p.$('.dp-plist .row[data-p="p-day"] [data-applied]')), 'D9 Applied indicator moves to the clicked preset');
  await p.click('.dp-plist .row:has-text("Focus") [data-del]');
  ok(!(await p.evaluate(() => OS.data.displays.presets.some((x) => x.name === 'Focus'))), 'Focus deleted');
  await popOpen();
  ok(!(await p.$('#pop .dp-chip:text-is("Focus")')), 'chip gone from popover');
  await popClose();

  console.log('ST-1 empty / unplug / failure');
  await scn('displays.empty');
  await openView();
  ok(/No presets yet/.test(await txt('.dp-plist')) && !!(await p.$('.dp-plist .state.empty')), 'empty: presets empty state');
  ok(!!(await p.$('[data-save]')), 'save control remains');
  await shot('view-empty');
  await scn('displays.empty');
  await scn('displays.unplug');
  ok((await p.evaluate(() => OS.data.displays.list.length)) === 1, 'unplug: list contains only built-in');
  await openView();
  ok((await p.$$('.dp-rect')).length === 1 && /No external displays/.test(await txt('.dp-arr')), 'view: one display + No external displays');
  await shot('view-unplugged');
  await popOpen();
  ok((await p.$$('#pop input[type=range]')).length === 1 && /No external displays/.test(await txt('#pop')) && !(await p.$('#pop [data-b="*"]')), 'popover: single slider + No external displays');
  await shot('popover-unplugged');
  await popClose();
  await scn('displays.unplug');
  ok((await p.evaluate(() => OS.data.displays.list.length)) === 3, 'reconnect restores the externals');
  await scn('displays.fail');
  await popOpen();
  ok(!!(await p.$('#pop .state.failure')) && !(await p.$('#pop [data-b]')) && /Try again/.test(await txt('#pop')), 'D3 Displays popover shows the store failure instead of data');
  await shot('popover-store-fail');
  await popClose();
  await p.click('[data-go=displays]'); await p.waitForSelector('.state.failure');
  ok(/Couldn’t load Displays/.test(await txt('#view')), 'failure state');
  await shot('view-failure');
  await scn('displays.fail');
  await p.click('#view [data-act]'); await p.waitForSelector('.dp-view');
  ok(true, 'Try again recovers');

  ok(errs.length === 0, 'no console errors' + (errs.length ? ': ' + errs.join(' | ') : ''));
  await b.close();
  console.log('displays: all passed');
})().catch((e) => { console.error(e.message); process.exit(1); });
